<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{Message,Modal}from'@arco-design/web-vue';import{adminApi,type AdminGroupMessage,type AdminGroupRow}from'@/api/admin';import{PublicApiError}from'@/api/client';import{formatDate,safeJSON}from'@/utils/format'
const groups=ref<AdminGroupRow[]>([]),messages=ref<AdminGroupMessage[]>([]),selected=ref<AdminGroupRow|null>(null),loading=ref(false),messageLoading=ref(false),hasMore=ref(false),next=ref(0),messageHasMore=ref(false),messageNext=ref(0),detail=ref<AdminGroupMessage|null>(null);const filters=reactive({search:'',status:0})
function report(e:unknown){Message.error(e instanceof PublicApiError?e.message:'请求失败')};async function load(append=false){loading.value=true;try{const page=await adminApi.groups({beforeId:append?next.value:undefined,limit:30,search:filters.search,status:filters.status});groups.value=append?[...groups.value,...page.list]:page.list;hasMore.value=page.hasMore;next.value=page.nextBeforeId}catch(e){report(e)}finally{loading.value=false}}
async function showMessages(group:AdminGroupRow,append=false){selected.value=group;messageLoading.value=true;try{const page=await adminApi.groupMessages(group.id,{beforeId:append?messageNext.value:undefined,limit:50});messages.value=append?[...messages.value,...page.list]:page.list;messageHasMore.value=page.hasMore;messageNext.value=page.nextBeforeId}catch(e){report(e)}finally{messageLoading.value=false}}
function dissolve(group:AdminGroupRow){Modal.warning({title:'解散群聊',content:`确认由管理员解散「${group.name}」？历史记录保留用于审计。`,hideCancel:false,onOk:async()=>{try{await adminApi.dissolveGroup(group.id);Message.success('群聊已解散');selected.value=null;await load()}catch(e){report(e)}}})}
function removeMessage(row:AdminGroupMessage){Modal.warning({title:'删除群消息',content:`确认移除群消息 #${row.id}？`,hideCancel:false,onOk:async()=>{try{await adminApi.deleteGroupMessage(row.id);Message.success('消息已删除');if(selected.value)await showMessages(selected.value)}catch(e){report(e)}}})};onMounted(()=>load())
</script>
<template><section class="page-stack"><a-card :bordered="false"><div class="toolbar"><div><h2>群聊管理</h2><p>群状态、成员/在线人数、消息量与群消息审计。</p></div><a-space><a-input v-model="filters.search" placeholder="群名称"/><a-select v-model="filters.status" style="width:130px"><a-option :value="0">全部状态</a-option><a-option :value="1">活跃</a-option><a-option :value="2">已解散</a-option></a-select><a-button type="primary" @click="load()">查询</a-button></a-space></div></a-card><a-card :bordered="false"><a-table row-key="id" :data="groups" :loading="loading" :pagination="false"><template #columns><a-table-column title="群"><template #cell="{record}"><div class="identity"><a-avatar :image-url="record.avatar||undefined">{{record.name.slice(0,1)}}</a-avatar><div><strong>{{record.name}}</strong><span>#{{record.id}} · 群主 {{record.ownerNickname}}</span></div></div></template></a-table-column><a-table-column title="状态" :width="100"><template #cell="{record}"><a-tag :color="record.status===1?'green':'gray'">{{record.status===1?'活跃':'已解散'}}</a-tag></template></a-table-column><a-table-column title="成员" :width="130"><template #cell="{record}">{{record.memberCount}} 人<br/>{{record.memberOnlineCount}} 在线</template></a-table-column><a-table-column title="消息" data-index="messageCount" :width="90"/><a-table-column title="创建时间" :width="180"><template #cell="{record}">{{formatDate(record.createdAt)}}</template></a-table-column><a-table-column title="操作" :width="180"><template #cell="{record}"><a-space><a-button size="small" @click="showMessages(record)">消息</a-button><a-button size="small" status="danger" :disabled="record.status===2" @click="dissolve(record)">解散</a-button></a-space></template></a-table-column></template></a-table><div class="load-more"><a-button v-if="hasMore" @click="load(true)">加载更多</a-button></div></a-card>
<a-card v-if="selected" :bordered="false" :title="`${selected.name} · 群消息`"><a-table row-key="id" :data="messages" :loading="messageLoading" :pagination="false"><template #columns><a-table-column title="ID" data-index="id" :width="80"/><a-table-column title="发送者"><template #cell="{record}">{{record.senderNickname}} (#{{record.senderId}})</template></a-table-column><a-table-column title="类型" data-index="messageType" :width="80"/><a-table-column title="预览" data-index="preview"/><a-table-column title="时间" :width="180"><template #cell="{record}">{{formatDate(record.createdAt)}}</template></a-table-column><a-table-column title="操作" :width="150"><template #cell="{record}"><a-space><a-button size="small" @click="detail=record">详情</a-button><a-button size="small" status="danger" @click="removeMessage(record)">删除</a-button></a-space></template></a-table-column></template></a-table><div class="load-more"><a-button v-if="messageHasMore" @click="showMessages(selected!,true)">加载更多</a-button></div></a-card><a-modal :visible="detail!==null" title="群消息详情" :footer="false" @cancel="detail=null"><pre class="safe-json">{{safeJSON(detail?.message)}}</pre></a-modal></section></template>
